  static String translate(String languageCode, String key) {
    return _localizedValues[languageCode]?[key] ?? _localizedValues['en']![key] ?? key;
  }
}

class AppLocalizations {
  final Locale locale;
  AppLocalizations(this.locale);

  static AppLocalizations? of(BuildContext context) {
    return Localizations.of<AppLocalizations>(context, AppLocalizations);
  }

  String translate(String key) {
    return AppTranslations.translate(locale.languageCode, key);
  }

  static const LocalizationsDelegate<AppLocalizations> delegate = _AppLocalizationsDelegate();
}

class _AppLocalizationsDelegate extends LocalizationsDelegate<AppLocalizations> {
  const _AppLocalizationsDelegate();

  @override
  bool isSupported(Locale locale) => true;

  @override
  Future<AppLocalizations> load(Locale locale) async {
    return AppLocalizations(locale);
  }

  @override
  bool shouldReload(_AppLocalizationsDelegate old) => false;
}

class SafeMaterialLocalizationsDelegate extends LocalizationsDelegate<MaterialLocalizations> {
  const SafeMaterialLocalizationsDelegate();

  @override
  bool isSupported(Locale locale) => true;

  @override
  Future<MaterialLocalizations> load(Locale locale) async {
    try {
      return await GlobalMaterialLocalizations.delegate.load(locale);
    } catch (e) {
      return await GlobalMaterialLocalizations.delegate.load(const Locale('en'));
    }
  }

  @override
  bool shouldReload(SafeMaterialLocalizationsDelegate old) => false;
}